#!/usr/bin/env python
"""Generate the final bounded speed SUP5 validation candidates."""

import argparse
from copy import deepcopy
from pathlib import Path

from omegaconf import OmegaConf

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "configs/paper/v4"
OUTPUT = ROOT / "configs/paper/v4_speed_sup5_candidates"
DATASETS = ("METRLA", "PEMSBAY")
LF_WEIGHT = 0.05
SUP5_SET = "candidate_unified_multiscale5_v1"

HEADER = (
    "# GENERATED by scripts/build_v4_speed_sup5_candidates.py -- do not edit.\n"
    "# Seed32 validation-only speed SUP5 study; test access is forbidden.\n"
)


def _plain(path):
    return OmegaConf.to_container(OmegaConf.load(path), resolve=True)


def _render(payload):
    return HEADER + OmegaConf.to_yaml(OmegaConf.create(payload), resolve=True)


def generated():
    paths = {}
    for dataset in DATASETS:
        destination = OUTPUT / dataset
        graph_final = _plain(SOURCE / f"experts/{dataset}_ALFGraph.yaml")
        graph_sup5 = deepcopy(graph_final)
        graph_sup5["runtime"]["model_variant"] = "alf_candidate_unified_sup5_v1"
        graph_sup5["family"]["recipe"].update({
            "moge_support_set": SUP5_SET,
            "candidate_validation_only": True,
        })
        paths[destination / "experts/ALFGraph_SUP5.yaml"] = _render(graph_sup5)

        outer = _plain(SOURCE / f"{dataset}_ALFNet.yaml")
        for name, use_lf in (("SUP5", False), ("LF_SUP5", True)):
            candidate = deepcopy(outer)
            candidate["runtime"]["model_variant"] = (
                f"alfnet_{dataset.lower()}_{name.lower()}_candidate")
            recipe = candidate["family"]["recipe"]
            recipe.update({
                "forecast_safe_relative_weight": LF_WEIGHT if use_lf else 0.0,
                "candidate_validation_only": True,
                "experimental_speed_safe_relative": bool(use_lf),
            })
            candidate["family"]["experts"]["graph"]["config_path"] = (
                f"./configs/paper/v4_speed_sup5_candidates/{dataset}/"
                "experts/ALFGraph_SUP5.yaml")
            paths[destination / f"{name}_ALFNet.yaml"] = _render(candidate)

        if dataset == "PEMSBAY":
            graph_legacy = deepcopy(graph_final)
            graph_legacy["runtime"]["model_variant"] = "alf_candidate_legacy5"
            graph_legacy["family"]["recipe"].update({
                "moge_support_set": "candidate_legacy5",
                "candidate_validation_only": True,
            })
            paths[destination / "experts/ALFGraph_BASE.yaml"] = _render(
                graph_legacy)

            base = deepcopy(outer)
            base["runtime"]["model_variant"] = "alfnet_pemsbay_base_candidate"
            base["family"]["recipe"].update({
                "forecast_safe_relative_weight": 0.0,
                "candidate_validation_only": True,
                "experimental_speed_safe_relative": False,
            })
            base["family"]["experts"]["graph"]["config_path"] = (
                "./configs/paper/v4_speed_sup5_candidates/PEMSBAY/"
                "experts/ALFGraph_BASE.yaml")
            paths[destination / "BASE_ALFNet.yaml"] = _render(base)

            control = _plain(SOURCE / "PEMSBAY_MoGERNN.yaml")
            control["runtime"]["model_variant"] = (
                "mogernn_pemsbay_speed_sup5_control")
            paths[destination / "CONTROL_MoGERNN.yaml"] = _render(control)
    return paths


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    failed = []
    for path, body in generated().items():
        if args.check:
            if not path.exists() or path.read_text("utf-8") != body:
                failed.append(path.relative_to(ROOT).as_posix())
        else:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(body, "utf-8")
            print(f"wrote {path.relative_to(ROOT)}")
    if failed:
        raise SystemExit("speed SUP5 configs differ: " + ", ".join(failed))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
